class Solution { fun gameOfLife(board:Array<IntArray>){val m=board.size;val n=board[0].size;for(r in 0 until m)for(c in 0 until n){var live=0;for(dr in -1..1)for(dc in -1..1){val nr=r+dr;val nc=c+dc;if((dr!=0||dc!=0)&&nr in 0 until m&&nc in 0 until n)live+=board[nr][nc] and 1};if(live==3||(live==2&&(board[r][c] and 1)==1))board[r][c]=board[r][c] or 2};for(row in board)for(c in 0 until n)row[c]=row[c] shr 1} }
